// Notices (spec 084): short messages for operators, shown behind the icon next to the version
// number in the dashboard.
//
// Two sources:
//   - REMOTE: `notices.json` at the root of the repository's main branch, fetched from
//     raw.githubusercontent.com (the same host family as the release check in github-release.ts).
//     It is edited in git like everything else. Its job is reaching installs that haven't
//     upgraded, such as "version X has a security problem, upgrade".
//   - LOCAL: generated by this server from its own state (the spec 083 primer review, …).
//
// The fetch is a plain GET with nothing attached: no version, no install id, no query string.
// Filtering happens HERE, on the install, so the request tells the far end nothing beyond the
// IP it comes from. Operators can switch it off (Settings → Dashboard, or
// LIBRARIAN_DISABLE_NOTICES=true). It is lazy (only when an admin opens the dashboard), cached,
// time-limited, size-capped, and never throws.
//
// Who sees a notice: `audience: "existing"` means only installs set up before the notice was
// created, so a new install a year from now doesn't inherit every notice ever written; `all`
// means every install. `versions` (a semver range) and `expires` narrow it further.

import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { type SettingsStore, primerReviewPending } from "@librarian/core";
import { z } from "zod";

const DEFAULT_REPO = "code-ministry-ltd/the-librarian";
const CACHE_TTL_MS = 6 * 60 * 60 * 1000; // 6 hours
const FAILURE_TTL_MS = 5 * 60 * 1000;
const REQUEST_TIMEOUT_MS = 4_000;
const MAX_BYTES = 64 * 1024;
const MAX_READ_IDS = 500;

/** Settings key: whether the server may fetch remote notices ("false" switches it off). */
export const NOTICES_FETCH_ENABLED_KEY = "notices.fetch.enabled";
/** Settings key: JSON array of notice ids the admin has read. */
export const NOTICES_READ_KEY = "notices.read";
/** Settings key: the install's first-boot date (ISO), for `audience: "existing"`. */
export const INSTALL_CREATED_AT_KEY = "install.createdAt";

const DATE = /^\d{4}-\d{2}-\d{2}$/;

const remoteNoticeSchema = z.object({
  id: z.string().min(1).max(100),
  created: z.string().regex(DATE),
  severity: z.enum(["info", "important", "security"]),
  title: z.string().min(1).max(200),
  body: z.string().max(2000),
  link: z
    .object({
      href: z.string().url().startsWith("https://"),
      label: z.string().min(1).max(100),
    })
    .optional(),
  audience: z.enum(["all", "existing"]),
  versions: z.string().max(100).optional(),
  expires: z.string().regex(DATE).optional(),
});

export type RemoteNotice = z.infer<typeof remoteNoticeSchema>;
export type NoticeSeverity = RemoteNotice["severity"];

/** A notice as the dashboard shows it. */
export interface Notice {
  id: string;
  created: string;
  severity: NoticeSeverity;
  title: string;
  body: string;
  /** An https URL for remote notices; a dashboard path for local ones. */
  link?: { href: string; label: string };
  source: "remote" | "local";
  read: boolean;
}

export type RemoteStatus =
  | { kind: "ok"; fetchedAt: string }
  | { kind: "disabled"; by: "setting" | "env" }
  | { kind: "unavailable"; reason: string };

/**
 * Parse `notices.json`. Entries that don't match the schema are skipped one by one, so a single
 * mistake in the file can't hide every other notice.
 */
export function parseNotices(raw: unknown): RemoteNotice[] {
  const list = (raw as { notices?: unknown } | null)?.notices;
  if (!Array.isArray(list)) return [];
  const out: RemoteNotice[] = [];
  for (const entry of list) {
    const parsed = remoteNoticeSchema.safeParse(entry);
    if (parsed.success) out.push(parsed.data);
  }
  return out;
}

// ── Version ranges ──────────────────────────────────────────────────────────

function parseVersion(v: string): [number, number, number] | null {
  const m = /^v?(\d+)\.(\d+)\.(\d+)/.exec(v.trim());
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

function compare(a: [number, number, number], b: [number, number, number]): number {
  for (let i = 0; i < 3; i++) if (a[i] !== b[i]) return a[i]! - b[i]!;
  return 0;
}

/**
 * Whether `version` satisfies `range`: space-separated comparators, all of which must hold, e.g.
 * ">=1.40.0 <1.47.0". Operators: >=, >, <=, <, = (or a bare version). An unparseable range or
 * version never matches, so a typo hides the notice rather than showing it to everyone.
 */
export function satisfies(version: string, range: string): boolean {
  const v = parseVersion(version);
  if (!v) return false;
  const parts = range.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return false;
  for (const part of parts) {
    const m = /^(>=|<=|>|<|=)?(.+)$/.exec(part);
    const target = m ? parseVersion(m[2]!) : null;
    if (!m || !target) return false;
    const c = compare(v, target);
    const op = m[1] ?? "=";
    const ok =
      op === ">="
        ? c >= 0
        : op === ">"
          ? c > 0
          : op === "<="
            ? c <= 0
            : op === "<"
              ? c < 0
              : c === 0;
    if (!ok) return false;
  }
  return true;
}

/**
 * The remote notices this install should see: in its audience, within the version range, not
 * expired. `today` and `installedOn` are YYYY-MM-DD (UTC). An `existing` notice is shown to an
 * install set up before the notice's `created` date; an install with no known date counts as
 * existing (it predates the date being recorded).
 */
export function visibleNotices(
  notices: readonly RemoteNotice[],
  ctx: { today: string; installedOn: string | null; version: string },
): RemoteNotice[] {
  return notices.filter((n) => {
    if (n.expires && ctx.today > n.expires) return false;
    if (n.audience === "existing" && ctx.installedOn && ctx.installedOn >= n.created) return false;
    if (n.versions && !satisfies(ctx.version, n.versions)) return false;
    return true;
  });
}

// ── Local notices ───────────────────────────────────────────────────────────

const PRIMER_REVIEW_ID = "local:primer-review";
export const TELEMETRY_NOTICE_ID = "local:telemetry";

/** State the local notices depend on that lives outside settings. */
export interface LocalNoticeContext {
  /** Usage stats (spec 085) are on and not forced off: the disclosure notice shows. */
  telemetryOn?: boolean;
}

/** Notices this server generates from its own state. */
export function localNotices(
  store: Pick<SettingsStore, "getSetting">,
  ctx: LocalNoticeContext = {},
): RemoteNotice[] {
  const out: RemoteNotice[] = [];
  if (ctx.telemetryOn) {
    // The disclosure (spec 085): shown before anything is sent, and for as long as stats are on.
    out.push({
      id: TELEMETRY_NOTICE_ID,
      created: "2026-11-04",
      severity: "important",
      title: "Anonymous usage stats are on",
      body:
        "Once a week this server sends the project a few anonymous facts: a random install id, " +
        "the version, the operating system, how it runs, which harness families are in use, a " +
        "rough memory count and three feature switches. Never your memories, names, paths or " +
        "exact numbers. Nothing goes until 24 hours after this notice first appeared. You can " +
        "see exactly what is sent, and turn it off, in Settings → Telemetry.",
      audience: "all",
    });
  }
  if (primerReviewPending(store)) {
    out.push({
      id: PRIMER_REVIEW_ID,
      created: "2026-11-03",
      severity: "important",
      title: "Review your primer addendum",
      body:
        "Your primer used to replace the default. It has been moved into the addendum, so " +
        "agents now get the default followed by your old text, which probably repeats some " +
        "of it. Trim it to what the default doesn't say.",
      audience: "all",
    });
  }
  return out;
}

/** Local notices link into the dashboard; remote ones carry their own https link. */
const LOCAL_LINKS: Record<string, { href: string; label: string }> = {
  [PRIMER_REVIEW_ID]: { href: "/settings/primer", label: "Open Settings → Primer" },
  [TELEMETRY_NOTICE_ID]: { href: "/settings/telemetry", label: "Open Settings → Telemetry" },
};

// ── Read state ──────────────────────────────────────────────────────────────

export function readIds(store: Pick<SettingsStore, "getSetting">): Set<string> {
  try {
    const raw = store.getSetting(NOTICES_READ_KEY);
    const parsed = raw ? (JSON.parse(raw) as unknown) : [];
    return new Set(Array.isArray(parsed) ? parsed.filter((x) => typeof x === "string") : []);
  } catch {
    return new Set();
  }
}

export function markRead(
  store: Pick<SettingsStore, "getSetting" | "setSetting">,
  ids: readonly string[],
): void {
  const known = readIds(store);
  const all = [...known, ...ids.filter((id) => !known.has(id))];
  store.setSetting(NOTICES_READ_KEY, JSON.stringify(all.slice(-MAX_READ_IDS)));
}

// ── Install date ────────────────────────────────────────────────────────────

/**
 * Record the install's first-boot date once (spec 084). An install that predates this setting
 * uses the date of its vault's first git commit, which is close to when it was set up; failing
 * that, today. Fail-soft: never blocks boot.
 */
export function ensureInstallDate(
  store: Pick<SettingsStore, "getSetting" | "setSetting">,
  vaultDir: string,
  now: Date = new Date(),
): void {
  try {
    if (store.getSetting(INSTALL_CREATED_AT_KEY)) return;
    store.setSetting(INSTALL_CREATED_AT_KEY, firstCommitDate(vaultDir) ?? now.toISOString());
  } catch {
    // fail-soft
  }
}

function firstCommitDate(vaultDir: string): string | null {
  if (!fs.existsSync(path.join(vaultDir, ".git"))) return null;
  try {
    const roots = execFileSync("git", ["-C", vaultDir, "rev-list", "--max-parents=0", "HEAD"], {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
      timeout: 5_000,
    })
      .trim()
      .split("\n")
      .filter(Boolean);
    let earliest: string | null = null;
    for (const root of roots) {
      const date = execFileSync("git", ["-C", vaultDir, "show", "-s", "--format=%cI", root], {
        encoding: "utf8",
        stdio: ["ignore", "pipe", "ignore"],
        timeout: 5_000,
      }).trim();
      const iso = new Date(date).toISOString();
      if (!earliest || iso < earliest) earliest = iso;
    }
    return earliest;
  } catch {
    return null;
  }
}

// ── Remote fetch ────────────────────────────────────────────────────────────

interface CacheEntry {
  fetchedAt: number;
  notices: RemoteNotice[];
  status: RemoteStatus;
}

let cache: CacheEntry | null = null;

function envDisabled(): boolean {
  return process.env.LIBRARIAN_DISABLE_NOTICES === "true";
}

export function fetchEnabledSetting(store: Pick<SettingsStore, "getSetting">): boolean {
  try {
    return store.getSetting(NOTICES_FETCH_ENABLED_KEY) !== "false";
  } catch {
    return true;
  }
}

export function noticesUrl(): string | null {
  const slug = process.env.LIBRARIAN_GITHUB_REPO || DEFAULT_REPO;
  if (!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(slug)) return null;
  return `https://raw.githubusercontent.com/${slug}/main/notices.json`;
}

async function fetchRemote(fetchImpl: typeof fetch): Promise<CacheEntry> {
  const now = Date.now();
  const url = noticesUrl();
  if (!url)
    return { fetchedAt: now, notices: [], status: { kind: "unavailable", reason: "invalid_repo" } };
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  try {
    // Nothing about this install goes out: a fixed user agent, no query, no cookies, no auth.
    const response = await fetchImpl(url, {
      headers: { accept: "application/json", "user-agent": "the-librarian" },
      signal: controller.signal,
      redirect: "error",
    });
    if (!response.ok) {
      return {
        fetchedAt: now,
        notices: [],
        status: { kind: "unavailable", reason: `http_${response.status}` },
      };
    }
    const text = await response.text();
    if (text.length > MAX_BYTES) {
      return { fetchedAt: now, notices: [], status: { kind: "unavailable", reason: "too_large" } };
    }
    const notices = parseNotices(JSON.parse(text));
    return {
      fetchedAt: now,
      notices,
      status: { kind: "ok", fetchedAt: new Date(now).toISOString() },
    };
  } catch (error) {
    const reason =
      error instanceof Error && error.name === "AbortError" ? "timeout" : "network_error";
    return { fetchedAt: now, notices: [], status: { kind: "unavailable", reason } };
  } finally {
    clearTimeout(timeout);
  }
}

/**
 * The remote notices and the fetch status. Fetches at most once per 6 hours (5 minutes after a
 * failure); keeps serving the last good list while a refetch fails. Never throws.
 */
export async function getRemoteNotices(
  store: Pick<SettingsStore, "getSetting">,
  fetchImpl: typeof fetch = fetch,
): Promise<{ notices: RemoteNotice[]; status: RemoteStatus }> {
  if (envDisabled()) return { notices: [], status: { kind: "disabled", by: "env" } };
  if (!fetchEnabledSetting(store))
    return { notices: [], status: { kind: "disabled", by: "setting" } };
  const now = Date.now();
  const ttl = cache?.status.kind === "ok" ? CACHE_TTL_MS : FAILURE_TTL_MS;
  if (cache && now - cache.fetchedAt < ttl) return { notices: cache.notices, status: cache.status };
  const next = await fetchRemote(fetchImpl);
  // A failed refetch keeps the last good notices, so a network blip doesn't empty the list.
  if (next.status.kind !== "ok" && cache?.status.kind === "ok") {
    cache = { ...cache, fetchedAt: now - CACHE_TTL_MS + FAILURE_TTL_MS };
    return { notices: cache.notices, status: next.status };
  }
  cache = next;
  return { notices: next.notices, status: next.status };
}

/** Test-only: forget the cache. */
export function __resetNoticesCacheForTests(): void {
  cache = null;
}

// ── Assembly ────────────────────────────────────────────────────────────────

function utcDay(d: Date): string {
  return d.toISOString().slice(0, 10);
}

/** Everything the dashboard shows: local notices first, then remote, newest first within each. */
export function assembleNotices(
  store: Pick<SettingsStore, "getSetting">,
  remote: readonly RemoteNotice[],
  ctx: { version: string; now?: Date } & LocalNoticeContext,
): Notice[] {
  const now = ctx.now ?? new Date();
  let installedOn: string | null = null;
  try {
    const raw = store.getSetting(INSTALL_CREATED_AT_KEY);
    installedOn = raw ? utcDay(new Date(raw)) : null;
  } catch {
    installedOn = null;
  }
  const read = readIds(store);
  const byNewest = (a: RemoteNotice, b: RemoteNotice) => b.created.localeCompare(a.created);
  const local = localNotices(store, ctx).sort(byNewest);
  const shown = visibleNotices(remote, { today: utcDay(now), installedOn, version: ctx.version })
    .filter((n) => !n.id.startsWith("local:"))
    .sort(byNewest);
  const view = (n: RemoteNotice, source: Notice["source"]): Notice => {
    const link = source === "local" ? LOCAL_LINKS[n.id] : n.link;
    return {
      id: n.id,
      created: n.created,
      severity: n.severity,
      title: n.title,
      body: n.body,
      ...(link ? { link } : {}),
      source,
      read: read.has(n.id),
    };
  };
  return [...local.map((n) => view(n, "local")), ...shown.map((n) => view(n, "remote"))];
}
